const $=id=>document.getElementById(id);
const esc=value=>String(value??'').replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;');
const api=(path,options={})=>window.EHSApi.request(path,options);
const STATUS={upcoming:['예정','upcoming'],pending:['제출대기','pending'],overdue_missing:['미제출','overdue_missing'],draft:['작성중','draft'],under_review:['심사중','under_review'],approved:['제출완료','approved'],changes_requested:['재제출 필요','changes_requested']};
let currentUser=null,annualData=null,activeDetail=null,busy=false;

window.AttachmentPreview.init({
  getPreviewTicket:file=>api(`/api/education/files/${encodeURIComponent(file.id)}/preview-ticket`,{method:'POST'}),
  download:file=>window.EHSApi.download(`/api/education/files/${encodeURIComponent(file.id)}`,file.file_name),
  maxPreviewBytes:25*1024*1024,
  onError:error=>console.error('education attachment preview failed',error)
});

function statusInfo(value){return STATUS[value]||['제출대기','pending']}
function statusBadge(value){const [label,cls]=statusInfo(value);return `<span class="badge ${cls}">${label}</span>`}
function formatBytes(value){const n=Number(value||0);if(n<1024)return `${n} B`;if(n<1024*1024)return `${Math.round(n/1024)} KB`;return `${Math.round(n/1024/1024*10)/10} MB`}
function dateTime(value){if(!value)return'-';const s=String(value).replace('T',' ').replace('Z','');return s.slice(0,16)}
function showToast(message){const el=$('toast');el.textContent=message;el.classList.remove('hidden');clearTimeout(showToast.timer);showToast.timer=setTimeout(()=>el.classList.add('hidden'),2600)}
function setBusy(value,label='처리 중...'){busy=value;document.querySelectorAll('#detailBody button,#detailBody input,#detailBody textarea').forEach(el=>el.disabled=value);const state=document.querySelector('#detailBody .busy-state');if(state)state.textContent=value?label:''}
function buildYears(){const now=new Date().getFullYear();for(let year=now+1;year>=now-4;year--){const option=document.createElement('option');option.value=year;option.textContent=`${year}년`;option.selected=year===now;$('year').append(option)}$('year').onchange=loadYear}
function goHome(){location.href='/home'}
$('homeBrand').onclick=goHome;$('homeBtn').onclick=goHome;$('logoutBtn').onclick=()=>window.EHSAuth.logout();$('refreshBtn').onclick=loadYear;

function renderSummary(summary){$('summary').innerHTML=`
  <div class="summary-card"><span>대상 협력사</span><b>${Number(summary.target_company_count||0)}개사</b></div>
  <div class="summary-card review"><span>심사중</span><b>${Number(summary.under_review_count||0)}건</b></div>
  <div class="summary-card approved"><span>제출완료</span><b>${Number(summary.approved_count||0)}건</b></div>
  <div class="summary-card changes"><span>재제출 필요</span><b>${Number(summary.changes_requested_count||0)}건</b></div>
  <div class="summary-card missing"><span>기한경과 미제출</span><b>${Number(summary.overdue_missing_count||0)}건</b></div>`}
function cellLabel(row){const [label]=statusInfo(row.effective_status);return label.replace('제출','제출<br>')}
function renderAdmin(){renderSummary(annualData.summary||{});const companies=annualData.companies||[];const head=`<div class="matrix-head"><span>협력사</span>${Array.from({length:12},(_,i)=>`<span>${i+1}월</span>`).join('')}</div>`;const rows=companies.map((company,companyIndex)=>`<div class="matrix-row"><div class="company"><b>${esc(company.company_name)}</b><small>${esc(company.industry_name||'')}</small></div>${company.months.map(month=>`<button class="status-cell ${esc(month.effective_status)}" type="button" data-company-index="${companyIndex}" data-month="${month.month}" aria-label="${esc(company.company_name)} ${month.month}월 ${statusInfo(month.effective_status)[0]}">${cellLabel(month)}</button>`).join('')}</div>`).join('');$('matrix').innerHTML=companies?`<div class="matrix">${head}${rows||'<div class="empty">등록된 협력사가 없습니다.</div>'}</div>`:'<div class="empty">등록된 협력사가 없습니다.</div>';$('matrix').querySelectorAll('.status-cell').forEach(button=>button.onclick=()=>openAdminMonth(Number(button.dataset.companyIndex),Number(button.dataset.month)))}
function renderPartner(){const company=annualData.companies?.[0];$('partnerCompany').textContent=company?`${company.company_name} 월별 교육자료`:'월별 교육자료';if(!company){$('months').innerHTML='<div class="empty" style="grid-column:1/-1">연결된 협력사 정보가 없습니다.</div>';return}$('months').innerHTML=company.months.map(month=>{const [label,cls]=statusInfo(month.effective_status);const disabled=month.effective_status==='upcoming'?'disabled':'';return `<button class="month-card ${cls}" type="button" data-month="${month.month}" ${disabled}><div class="month-top"><span class="month-no">${month.month}월</span><span class="month-files">${Number(month.file_count||0)}개 파일</span></div><div class="month-status ${cls}">${label}</div><div class="month-updated">${month.updated_at?`최종 수정 ${esc(dateTime(month.updated_at))}`:month.effective_status==='upcoming'?'제출기간 전':'자료를 등록해 주세요.'}</div></button>`}).join('');$('months').querySelectorAll('.month-card:not(:disabled)').forEach(button=>button.onclick=()=>openPartnerMonth(Number(button.dataset.month)))}

async function loadYear(){closeDetail();const year=Number($('year').value);if(currentUser.role==='admin')$('matrix').innerHTML='<div class="loading">불러오는 중...</div>';else $('months').innerHTML='<div class="loading" style="grid-column:1/-1">불러오는 중...</div>';try{annualData=await api(`/api/education?year=${year}`);currentUser.role==='admin'?renderAdmin():renderPartner()}catch(error){const target=currentUser.role==='admin'?$('matrix'):$('months');target.innerHTML=`<div class="error" style="grid-column:1/-1">${esc(error.message)}</div>`}}
function openModal(title,sub){$('detailTitle').textContent=title;$('detailSub').textContent=sub||'';$('detailModal').classList.remove('hidden')}
function closeDetail(){if(busy)return;activeDetail=null;$('detailModal').classList.add('hidden');$('detailBody').innerHTML=''}
$('detailClose').onclick=closeDetail;$('detailModal').onclick=event=>{if(event.target===$('detailModal'))closeDetail()};

function fileRows(files,{editable=false}={}){if(!files?.length)return'<div class="empty">첨부된 파일이 없습니다.</div>';return files.map(file=>`<div class="file-row"><div class="file-name"><b title="${esc(file.file_name)}">${esc(file.file_name)}</b><span>${formatBytes(file.file_size)} · ${esc(dateTime(file.created_at))}</span></div><div class="file-actions"><button class="mini preview-file" type="button" data-id="${esc(file.id)}" data-name="${esc(file.file_name)}" data-size="${Number(file.file_size||0)}" data-type="${esc(file.content_type||'')}">미리보기</button><button class="mini download-file" type="button" data-id="${esc(file.id)}" data-name="${esc(file.file_name)}">다운로드</button>${editable?`<button class="mini danger delete-file" type="button" data-id="${esc(file.id)}" data-name="${esc(file.file_name)}">삭제</button>`:''}</div></div>`).join('')}
function bindFileActions(){document.querySelectorAll('#detailBody .preview-file').forEach(button=>button.onclick=()=>window.AttachmentPreview.open({id:button.dataset.id,file_name:button.dataset.name,file_size:Number(button.dataset.size||0),content_type:button.dataset.type||''}));document.querySelectorAll('#detailBody .download-file').forEach(button=>button.onclick=()=>window.EHSApi.download(`/api/education/files/${encodeURIComponent(button.dataset.id)}`,button.dataset.name));document.querySelectorAll('#detailBody .delete-file').forEach(button=>button.onclick=()=>deleteFile(button.dataset.id,button.dataset.name))}

async function openPartnerMonth(month){openModal(`${month}월 교육자료 제출`,`${$('year').value}년 · ${currentUser.company_name||''}`);$('detailBody').innerHTML='<div class="loading">제출정보를 불러오는 중...</div>';try{const data=await api(`/api/education/months/${$('year').value}/${month}`);activeDetail=data.submission;renderPartnerDetail(data.submission,data.capabilities||{})}catch(error){$('detailBody').innerHTML=`<div class="error">${esc(error.message)}</div>`}}
function renderPartnerDetail(submission,capabilities){const editable=capabilities.editable!==false;const files=submission.files||[];$('detailBody').innerHTML=`<div class="status-line">${statusBadge(submission.effective_status)}<span style="color:#8b969e;font-size:9.5px">${submission.submitted_at?`제출 ${esc(dateTime(submission.submitted_at))}`:'파일을 첨부한 뒤 제출해 주세요.'}</span></div>${submission.review_comment?`<div class="review-comment"><b>관리자 심사의견</b><br>${esc(submission.review_comment)}</div>`:''}<section class="section"><div class="section-head"><strong>교육 결과자료</strong><span>${files.length}/10개 · PDF/한글/Excel/PPT/Word/이미지</span></div><div class="files">${fileRows(files,{editable})}</div>${editable?`<div class="upload"><input id="educationFiles" type="file" multiple accept=".pdf,.hwp,.hwpx,.xls,.xlsx,.ppt,.pptx,.doc,.docx,.jpg,.jpeg,.png"><label for="educationFiles">파일 선택</label><p>파일당 25MB, 월 합계 100MB 이하 · 최대 10개</p></div>`:''}</section><section class="section field"><label for="educationNote">제출 메모</label><textarea id="educationNote" maxlength="2000" ${editable?'':'disabled'} placeholder="교육명, 교육일 또는 확인이 필요한 내용을 입력하세요.">${esc(submission.note||'')}</textarea></section><div class="actions"><span class="busy busy-state"></span><span class="grow"></span><button class="btn" type="button" onclick="closeDetail()">닫기</button>${editable?'<button class="btn" id="saveNote" type="button">임시저장</button><button class="btn primary" id="submitEducation" type="button">심사 제출</button>':''}</div>`;bindFileActions();if(editable){$('educationFiles').onchange=uploadFiles;$('saveNote').onclick=saveNote;$('submitEducation').onclick=submitEducation}}
async function refreshPartnerDetail(){const month=Number(activeDetail.education_month);const data=await api(`/api/education/months/${$('year').value}/${month}`);activeDetail=data.submission;renderPartnerDetail(data.submission,data.capabilities||{});await reloadAnnualSilently()}
async function uploadFiles(event){const files=[...event.target.files];if(!files.length)return;setBusy(true,'업로드 중...');try{for(let index=0;index<files.length;index++){const form=new FormData();form.append('file',files[index]);const state=document.querySelector('#detailBody .busy-state');if(state)state.textContent=`업로드 중 ${index+1}/${files.length}`;await api(`/api/education/months/${activeDetail.education_year}/${activeDetail.education_month}/files`,{method:'POST',body:form})}showToast('교육자료 파일을 등록했습니다.');setBusy(false);await refreshPartnerDetail()}catch(error){setBusy(false);alert(error.message)}}
async function saveNote(){setBusy(true,'저장 중...');try{const data=await api(`/api/education/months/${activeDetail.education_year}/${activeDetail.education_month}`,{method:'PATCH',body:JSON.stringify({note:$('educationNote').value})});activeDetail=data.submission;showToast('임시저장했습니다.');setBusy(false);await refreshPartnerDetail()}catch(error){setBusy(false);alert(error.message)}}
async function submitEducation(){if(!(activeDetail.files||[]).length){alert('교육자료 파일을 1개 이상 첨부하세요.');return}if(!confirm(`${activeDetail.education_month}월 교육자료를 관리자 심사로 제출할까요?`))return;setBusy(true,'제출 중...');try{const data=await api(`/api/education/months/${activeDetail.education_year}/${activeDetail.education_month}/submit`,{method:'POST',body:JSON.stringify({note:$('educationNote').value})});activeDetail=data.submission;showToast('교육자료를 제출했습니다.');setBusy(false);await refreshPartnerDetail()}catch(error){setBusy(false);alert(error.message)}}
async function deleteFile(fileId,fileName){if(!confirm(`${fileName} 파일을 삭제할까요? 제출상태는 작성중으로 변경됩니다.`))return;setBusy(true,'삭제 중...');try{await api(`/api/education/files/${encodeURIComponent(fileId)}`,{method:'DELETE'});showToast('파일을 삭제했습니다.');setBusy(false);await refreshPartnerDetail()}catch(error){setBusy(false);alert(error.message)}}

async function openAdminMonth(companyIndex,monthNumber){const company=annualData.companies[companyIndex],month=company.months.find(item=>item.month===monthNumber);openModal(`${company.company_name} · ${monthNumber}월 교육자료`,`${$('year').value}년 교육 제출 심사`);activeDetail={company,month};if(!month.submission_id){$('detailBody').innerHTML=`<div class="status-line">${statusBadge(month.effective_status)}</div><div class="empty">제출된 교육자료가 없습니다.</div><div class="actions"><span class="grow"></span><button class="btn" type="button" onclick="closeDetail()">닫기</button></div>`;return}$('detailBody').innerHTML='<div class="loading">제출자료를 불러오는 중...</div>';try{const data=await api(`/api/education/submissions/${encodeURIComponent(month.submission_id)}`);activeDetail=data.submission;renderAdminDetail(data.submission)}catch(error){$('detailBody').innerHTML=`<div class="error">${esc(error.message)}</div>`}}
function renderAdminDetail(submission){const files=submission.files||[];$('detailBody').innerHTML=`<div class="status-line">${statusBadge(submission.effective_status)}<span style="color:#8b969e;font-size:9.5px">${submission.submitted_at?`제출 ${esc(dateTime(submission.submitted_at))}`:'아직 심사 제출되지 않았습니다.'}</span></div>${submission.review_comment?`<div class="review-comment"><b>심사의견</b><br>${esc(submission.review_comment)}</div>`:''}<section class="section"><div class="section-head"><strong>제출 파일</strong><span>${files.length}개 · ${formatBytes(submission.file_bytes)}</span></div><div class="files">${fileRows(files)}</div></section><section class="section field"><label>협력사 제출 메모</label><textarea disabled>${esc(submission.note||'')}</textarea></section>${submission.status==='under_review'?`<section class="section review-box"><div class="section-head"><strong>관리자 심사</strong><span>승인 또는 재제출 요청</span></div><textarea id="reviewComment" maxlength="2000" placeholder="보완이 필요한 경우 사유를 입력하세요."></textarea><div class="review-tools"><button class="btn danger" id="requestChanges" type="button">재제출 요청</button><button class="btn primary" id="approveEducation" type="button">제출완료 승인</button></div></section>`:''}<div class="actions"><span class="busy busy-state"></span><span class="grow"></span><button class="btn" type="button" onclick="closeDetail()">닫기</button></div>`;bindFileActions();if(submission.status==='under_review'){$('requestChanges').onclick=()=>reviewEducation('request_changes');$('approveEducation').onclick=()=>reviewEducation('approve')}}
async function reviewEducation(action){const comment=$('reviewComment').value.trim();if(action==='request_changes'&&!comment){alert('재제출 요청 사유를 입력하세요.');return}const message=action==='approve'?'제출완료로 승인할까요?':'협력사에 재제출을 요청할까요?';if(!confirm(message))return;setBusy(true,'심사 저장 중...');try{const data=await api(`/api/admin/education/${encodeURIComponent(activeDetail.id)}/review`,{method:'PATCH',body:JSON.stringify({action,comment})});activeDetail=data.submission;renderAdminDetail(data.submission);showToast(action==='approve'?'제출완료 처리했습니다.':'재제출을 요청했습니다.');await reloadAnnualSilently()}catch(error){setBusy(false);alert(error.message)}}
async function reloadAnnualSilently(){try{annualData=await api(`/api/education?year=${$('year').value}`);currentUser.role==='admin'?renderAdmin():renderPartner()}catch(error){console.error('education overview refresh failed',error)}}

(async()=>{try{currentUser=await window.EHSAuth.requireUser();const admin=currentUser.role==='admin';$('pageTitle').textContent=admin?'교육 제출현황':'교육자료 제출';$('pageMeta').textContent=admin?'협력사별 월간 교육자료 제출 여부를 확인하고 심사합니다.':'월별 안전보건 교육자료를 제출하고 심사상태를 확인합니다.';$('adminPanel').classList.toggle('hidden',!admin);$('partnerPanel').classList.toggle('hidden',admin);$('userLabel').textContent=[currentUser.company_name,currentUser.position,currentUser.name].filter(Boolean).join(' · ')||currentUser.email||'';buildYears();await loadYear()}catch(error){if(error?.status===401)return;document.querySelector('.shell').innerHTML=`<div class="error">${esc(window.EHSApi?.describe?window.EHSApi.describe(error):error.message)}</div>`}})();
